-- ---- 3. Vérifications (la migration échoue si le compte n'y est pas) --------

do $check$
declare
	v_pts integer; v_sans_noeud integer; v_refs integer;
	v_algo integer; v_demo integer; v_appro integer; v_regime integer; v_anciens integer;
begin
	select count(*) into v_pts from public.curriculum_points where grade = 'T_COMP';
	select count(*) into v_sans_noeud from public.curriculum_points where grade = 'T_COMP' and node_id is null;
	select count(*) into v_refs from public.curriculum_point_automatismes where grade = 'T_COMP';
	select count(*) into v_algo from public.curriculum_points where grade = 'T_COMP' and kind = 'algorithme';
	select count(*) into v_demo from public.curriculum_points where grade = 'T_COMP' and kind = 'demonstration';
	select count(*) into v_appro from public.curriculum_points where grade = 'T_COMP' and exigence = 'approfondissement';
	select count(*) into v_regime from public.curriculum_points where grade = 'T_COMP' and regime_acquisition <> 'diversite';
	-- L'ancien seed (grade NULL, rattaché aux objectifs) est intact.
	select count(*) into v_anciens from public.curriculum_points
	 where code ~ '^TCOMP-(0\d\d|1[0-3]\d)$' and grade is null and objective_id is not null;
	if v_pts <> 129 or v_sans_noeud <> 0 or v_refs <> 97
	   or v_algo <> 10 or v_demo <> 12 or v_appro <> 23 or v_regime <> 0
	   or v_anciens <> 139 then
		raise exception 'seed Tle comp. incohérent : points=%, sans nœud=%, réfs=%, algo=%, dém=%, appro=%, non-diversité=%, anciens=%',
			v_pts, v_sans_noeud, v_refs, v_algo, v_demo, v_appro, v_regime, v_anciens;
	end if;
end $check$;
